begin;
create table public.world_companies(party_id uuid primary key references public.world_parties(id) on delete cascade,owner_user_id uuid not null references auth.users(id) on delete cascade,name text not null,treasury bigint not null default 250 check(treasury>=0),member_capacity integer not null default 12 check(member_capacity between 1 and 500),revision bigint not null default 1,updated_at timestamptz not null default now());
create table public.world_company_members(id uuid primary key default gen_random_uuid(),party_id uuid not null references public.world_companies(party_id) on delete cascade,recruit_key text not null,name text not null,role text not null check(role in('infantry','ranger','medic','engineer','scout')),tier smallint not null default 1 check(tier between 1 and 10),health numeric(6,3) not null default 100 check(health between 0 and 100),wage bigint not null default 0 check(wage>=0),status text not null default 'active' check(status in('active','wounded','recovering','dismissed')),joined_at timestamptz not null default now());
create table public.world_recruitment_offers(location_id uuid not null references public.world_locations(id) on delete cascade,recruit_key text not null,name text not null,role text not null check(role in('infantry','ranger','medic','engineer','scout')),tier smallint not null default 1,price bigint not null check(price>=0),wage bigint not null default 0,available integer not null default 0 check(available>=0),revision bigint not null default 1,primary key(location_id,recruit_key));
create table public.world_town_services(location_id uuid not null references public.world_locations(id) on delete cascade,service_key text not null check(service_key in('rest','heal_company','repair_equipment')),price bigint not null check(price>=0),enabled boolean not null default true,revision bigint not null default 1,primary key(location_id,service_key));
create table public.world_supply_offers(location_id uuid not null references public.world_locations(id) on delete cascade,supply_key text not null check(supply_key in('food','ammunition','medicine','parts')),unit_price bigint not null check(unit_price>=0),stock numeric(16,3) not null check(stock>=0),revision bigint not null default 1,primary key(location_id,supply_key));
create table public.world_company_commands(owner_user_id uuid not null references auth.users(id) on delete cascade,request_id text not null check(length(request_id) between 1 and 96),party_id uuid not null references public.world_companies(party_id) on delete cascade,action text not null,expected_revision bigint not null,payload jsonb not null,response jsonb,created_at timestamptz not null default now(),primary key(owner_user_id,request_id));
do $$ declare t text; begin foreach t in array array['world_companies','world_company_members','world_recruitment_offers','world_town_services','world_supply_offers','world_company_commands'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy world_company_owner_read on public.world_companies for select to authenticated using(owner_user_id=auth.uid());
create policy world_company_members_owner_read on public.world_company_members for select to authenticated using(exists(select 1 from public.world_companies c where c.party_id=world_company_members.party_id and c.owner_user_id=auth.uid()));
create policy world_company_commands_owner_read on public.world_company_commands for select to authenticated using(owner_user_id=auth.uid());
create policy world_recruitment_read on public.world_recruitment_offers for select to authenticated using(true);
create policy world_town_services_read on public.world_town_services for select to authenticated using(true);
create policy world_supply_offers_read on public.world_supply_offers for select to authenticated using(true);
create or replace function public.bootstrap_player_company() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$ begin if new.kind='player' and new.owner_user_id is not null then insert into public.world_companies(party_id,owner_user_id,name) values(new.id,new.owner_user_id,new.name) on conflict do nothing; insert into public.world_supplies(party_id,supply_key,quantity,consumption_per_tick) values(new.id,'food',20,.02),(new.id,'ammunition',12,.01),(new.id,'medicine',4,0) on conflict do nothing; end if; return new; end $$;
create trigger world_party_bootstrap_company after insert on public.world_parties for each row execute function public.bootstrap_player_company();
insert into public.world_companies(party_id,owner_user_id,name) select id,owner_user_id,name from public.world_parties where kind='player' and owner_user_id is not null on conflict do nothing;
insert into public.world_recruitment_offers(location_id,recruit_key,name,role,tier,price,wage,available) select id,'greenfall_militia','Greenfall Militia','infantry',1,60,2,8 from public.world_locations where key='greenfall-crossing';
insert into public.world_recruitment_offers(location_id,recruit_key,name,role,tier,price,wage,available) select id,'greenfall_ranger','Greenfall Ranger','ranger',1,90,3,4 from public.world_locations where key='greenfall-crossing';
insert into public.world_town_services(location_id,service_key,price) select id,s.key,s.price from public.world_locations cross join(values('rest',15),('heal_company',35),('repair_equipment',25))s(key,price) where world_locations.key='greenfall-crossing';
insert into public.world_supply_offers(location_id,supply_key,unit_price,stock) select id,s.key,s.price,s.stock from public.world_locations cross join(values('food',2,500::numeric),('ammunition',4,300::numeric),('medicine',8,100::numeric),('parts',6,150::numeric))s(key,price,stock) where world_locations.key='greenfall-crossing';
create or replace function public.living_world_company_command(p_actor uuid,p_request_id text,p_party uuid,p_expected_revision bigint,p_action text,p_payload jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$
declare c public.world_companies%rowtype; old public.world_company_commands%rowtype; p public.world_parties%rowtype; r public.world_recruitment_offers%rowtype; s public.world_supply_offers%rowtype; v public.world_town_services%rowtype; q integer; cost bigint; n integer; result jsonb;
begin
if coalesce(auth.role(),'')<>'service_role' then raise exception 'service_role_required'; end if;
if p_request_id is null or length(p_request_id) not between 1 and 96 or p_action not in('recruit','buy_supplies','use_town_service') then raise exception 'invalid_company_command'; end if;
select * into old from public.world_company_commands where owner_user_id=p_actor and request_id=p_request_id; if found then if old.party_id<>p_party or old.action<>p_action or old.expected_revision<>p_expected_revision or old.payload<>p_payload then raise exception 'idempotency_conflict'; end if; return old.response||jsonb_build_object('duplicate',true); end if;
select * into c from public.world_companies where party_id=p_party for update; if not found then raise exception 'company_not_found'; end if; if c.owner_user_id<>p_actor then raise exception 'unauthorized_ownership'; end if; if c.revision<>p_expected_revision then raise exception 'stale_company'; end if;
select * into p from public.world_parties where id=p_party for update; if p.location_id is null then raise exception 'town_required'; end if;
insert into public.world_company_commands(owner_user_id,request_id,party_id,action,expected_revision,payload)values(p_actor,p_request_id,p_party,p_action,p_expected_revision,p_payload);
if p_action='recruit' then q:=coalesce((p_payload->>'quantity')::integer,0); if q not between 1 and 20 then raise exception 'invalid_quantity'; end if; select * into r from public.world_recruitment_offers where location_id=p.location_id and recruit_key=p_payload->>'recruitKey' for update; if not found or r.available<q then raise exception 'recruit_unavailable'; end if; select count(*) into n from public.world_company_members where party_id=p_party and status<>'dismissed'; if n+q>c.member_capacity then raise exception 'company_capacity'; end if; cost:=r.price*q; if c.treasury<cost then raise exception 'insufficient_treasury'; end if; insert into public.world_company_members(party_id,recruit_key,name,role,tier,wage)select p_party,r.recruit_key,r.name,r.role,r.tier,r.wage from generate_series(1,q); update public.world_recruitment_offers set available=available-q,revision=revision+1 where location_id=r.location_id and recruit_key=r.recruit_key;
elsif p_action='buy_supplies' then q:=coalesce((p_payload->>'quantity')::integer,0); if q not between 1 and 1000 then raise exception 'invalid_quantity'; end if; select * into s from public.world_supply_offers where location_id=p.location_id and supply_key=p_payload->>'supplyKey' for update; if not found or s.stock<q then raise exception 'supply_unavailable'; end if; cost:=s.unit_price*q; if c.treasury<cost then raise exception 'insufficient_treasury'; end if; update public.world_supply_offers set stock=stock-q,revision=revision+1 where location_id=s.location_id and supply_key=s.supply_key; insert into public.world_supplies(party_id,supply_key,quantity)values(p_party,s.supply_key,q)on conflict(party_id,supply_key)do update set quantity=world_supplies.quantity+excluded.quantity,revision=world_supplies.revision+1;
else select * into v from public.world_town_services where location_id=p.location_id and service_key=p_payload->>'serviceKey' and enabled for update; if not found then raise exception 'service_unavailable'; end if; cost:=v.price; if c.treasury<cost then raise exception 'insufficient_treasury'; end if; if v.service_key='rest' then update public.world_parties set fatigue=0,morale=least(100,morale+15),revision=revision+1,updated_at=now()where id=p_party; elsif v.service_key='heal_company' then update public.world_company_members set health=100,status='active' where party_id=p_party and status in('wounded','recovering'); else update public.world_armies set formation=formation||'{"equipmentCondition":100}'::jsonb,revision=revision+1 where party_id=p_party; end if; end if;
update public.world_companies set treasury=treasury-cost,revision=revision+1,updated_at=now()where party_id=p_party returning * into c; result:=jsonb_build_object('ok',true,'duplicate',false,'action',p_action,'cost',cost,'treasury',c.treasury,'companyRevision',c.revision); update public.world_company_commands set response=result where owner_user_id=p_actor and request_id=p_request_id; return result;
end $$;
revoke all on function public.living_world_company_command(uuid,text,uuid,bigint,text,jsonb) from public,anon,authenticated; grant execute on function public.living_world_company_command(uuid,text,uuid,bigint,text,jsonb) to service_role;
commit;
